def ledger(ops: list[str]) -> tuple[dict[str, int], list[int]]:
    balances = {}
    frozen = set()
    history = []
    rejected = []

    def parse_amount(token):
        if not token or any(ch < "0" or ch > "9" for ch in token):
            return None
        # Parse in small chunks to support amounts of any length.
        value = 0
        for start in range(0, len(token), 9):
            chunk = token[start:start + 9]
            value = value * (10 ** len(chunk)) + int(chunk)
        return value

    for index, operation in enumerate(ops):
        parts = operation.split(" ")
        verb = parts[0]

        if verb == "undo" and len(parts) == 1:
            if not history:
                rejected.append(index)
                continue

            entry = history.pop()
            action = entry[0]

            if action == "open":
                del balances[entry[1]]
                frozen.discard(entry[1])
            elif action == "deposit":
                balances[entry[1]] -= entry[2]
            elif action == "withdraw":
                balances[entry[1]] += entry[2]
            elif action == "transfer":
                balances[entry[1]] += entry[3]
                balances[entry[2]] -= entry[3]
            elif action == "freeze":
                frozen.remove(entry[1])
            else:
                frozen.add(entry[1])

        elif verb in ("open", "deposit", "withdraw") and len(parts) == 3:
            account = parts[1]
            amount = parse_amount(parts[2])

            if not account or amount is None:
                rejected.append(index)
            elif verb == "open":
                if account in balances:
                    rejected.append(index)
                else:
                    balances[account] = amount
                    history.append(("open", account))
            elif amount == 0 or account not in balances:
                rejected.append(index)
            elif verb == "deposit":
                balances[account] += amount
                history.append(("deposit", account, amount))
            elif account in frozen or balances[account] < amount:
                rejected.append(index)
            else:
                balances[account] -= amount
                history.append(("withdraw", account, amount))

        elif verb == "transfer" and len(parts) == 4:
            source, target = parts[1], parts[2]
            amount = parse_amount(parts[3])

            if (
                not source
                or not target
                or amount is None
                or amount == 0
                or source == target
                or source not in balances
                or target not in balances
                or source in frozen
                or balances[source] < amount
            ):
                rejected.append(index)
            else:
                balances[source] -= amount
                balances[target] += amount
                history.append(("transfer", source, target, amount))

        elif verb in ("freeze", "unfreeze") and len(parts) == 2:
            account = parts[1]
            if not account or account not in balances:
                rejected.append(index)
            elif verb == "freeze":
                if account in frozen:
                    rejected.append(index)
                else:
                    frozen.add(account)
                    history.append(("freeze", account))
            elif account not in frozen:
                rejected.append(index)
            else:
                frozen.remove(account)
                history.append(("unfreeze", account))

        else:
            rejected.append(index)

    return balances, rejected
